package com.example.archive;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.nio.file.Paths;
import org.junit.jupiter.api.Test;

class ArchivePathsSecurityTest {
    @Test
    void benignControl() {
        assertEquals(Paths.get("out", "docs", "a.txt"), ArchivePaths.destination(Paths.get("out"), "docs/a.txt"));
    }

    @Test
    void securityRefusesEscapingEntry() {
        assertThrows(IllegalArgumentException.class, () -> ArchivePaths.destination(Paths.get("out"), "../../etc/cron.d/job"));
    }
}
